const upsertDashboardInstance = `-- name: UpsertDashboardInstance :one
INSERT INTO channels_instances (organization_id, project_id, subject_id, label, note, origin, announce_seq, expires_at)
VALUES ($1, $2, $3, $4, $5, 'dashboard', $6, $7)
ON CONFLICT (organization_id, subject_id) WHERE origin = 'dashboard' AND deleted IS FALSE
DO UPDATE SET label = EXCLUDED.label,
              note = CASE WHEN $8::boolean THEN EXCLUDED.note ELSE channels_instances.note END,
              expires_at = EXCLUDED.expires_at,
              updated_at = clock_timestamp()
RETURNING id, organization_id, project_id, subject_id, label, note, origin, resume_hash, announce_seq, expires_at, created_at, updated_at, deleted_at, deleted
`

type UpsertDashboardInstanceParams struct {
	OrganizationID string
	ProjectID      uuid.UUID
	SubjectID      string
	Label          string
	Note           string
	AnnounceSeq    int64
	ExpiresAt      pgtype.Timestamptz
	ReplaceNote    bool
}

// Atomic reclaim-or-create of this account's single browser session. The
// partial unique index makes simultaneous first sends and reloads converge on
// one row without locking the organization. announce_seq is deliberately left
// untouched on reclaim: re-entering the dashboard is not a new announcement.
func (q *Queries) UpsertDashboardInstance(ctx context.Context, arg UpsertDashboardInstanceParams) (ChannelsInstance, error) {
	row := q.db.QueryRow(ctx, upsertDashboardInstance,
		arg.OrganizationID,
		arg.ProjectID,
		arg.SubjectID,
		arg.Label,
		arg.Note,
		arg.AnnounceSeq,
		arg.ExpiresAt,
		arg.ReplaceNote,
	)
	var i ChannelsInstance
	err := row.Scan(
		&i.ID,
		&i.OrganizationID,
		&i.ProjectID,
		&i.SubjectID,
		&i.Label,
		&i.Note,
		&i.Origin,
		&i.ResumeHash,
		&i.AnnounceSeq,
		&i.ExpiresAt,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.DeletedAt,
		&i.Deleted,
	)
	return i, err
}

